const articleLink = document.querySelector('section [data-id="50025740"], section a[href*="/story/"]') || 
                    document.querySelector('h2:contains("Top 50 USMNT")') ||
                    Array.from(document.querySelectorAll('h2')).find(el => el.textContent.includes('Top 50 USMNT'))?.closest('a');
const h2Elements = Array.from(document.querySelectorAll('h2'));
const topHeadline = h2Elements.find(el => el.textContent.includes('Top 50 USMNT'));
let parentLink = topHeadline;
while (parentLink && parentLink.tagName !== 'A') {
  parentLink = parentLink.parentElement;
}
return {
  headline: topHeadline ? topHeadline.textContent.trim() : null,
  link: parentLink ? parentLink.href : null,
  description: document.querySelector('p')?.textContent.trim().substring(0, 200)
};

const article = document.querySelector('article') || document.querySelector('.article-body') || document.querySelector('main');
const paragraphs = article ? Array.from(article.querySelectorAll('p')).map(p => p.textContent.trim()).filter(p => p.length > 50) : [];
const headings = article ? Array.from(article.querySelectorAll('h2, h3, h4')).map(h => h.textContent.trim()) : [];
return {
  url: window.location.href,
  title: document.title,
  paragraphCount: paragraphs.length,
  firstFewParagraphs: paragraphs.slice(0, 5),
  headings: headings.slice(0, 15)
};

const allP = Array.from(document.querySelectorAll('p'));
const paragraphs = allP.map(p => p.textContent.trim()).filter(p => p.length > 50);
const allHeadings = Array.from(document.querySelectorAll('h2, h3, h4, h5'));
const headings = allHeadings.map(h => h.textContent.trim()).filter(h => h.length > 0);
return {
  url: window.location.href,
  title: document.title,
  paragraphCount: paragraphs.length,
  firstParagraphs: paragraphs.slice(0, 8),
  headings: headings.slice(0, 20)
};
